{
  "decision-schedule-laundry-with-solar-headroom": "WITH pairs AS (SELECT w.start_hour AS wash_hour, d.start_hour AS dry_hour, max(0, 2 - w.spare_solar_kwh) AS wash_grid, max(0, 3 - d.spare_solar_kwh) AS dry_grid, w.grid_room_kwh AS wash_room, d.grid_room_kwh AS dry_room, w.price_cents AS wash_price, d.price_cents AS dry_price FROM hour_offer AS w JOIN hour_offer AS d ON d.start_hour - w.start_hour BETWEEN 1 AND 2) SELECT wash_hour, dry_hour, wash_grid * wash_price + dry_grid * dry_price AS cost_cents FROM pairs WHERE wash_grid <= wash_room AND dry_grid <= dry_room ORDER BY cost_cents, wash_hour, dry_hour LIMIT 1",
  "decision-schedule-reset-checks-before-dispatch": "WITH plans(first_job, second_job, saved_packages, cost_cents) AS (SELECT job_code, NULL, saved_count, kit_cents FROM reset_job UNION ALL SELECT a.job_code, b.job_code, a.saved_count + b.saved_count, a.kit_cents + b.kit_cents FROM reset_job AS a JOIN reset_job AS b ON a.job_code < b.job_code AND (a.finish_min <= b.start_min OR b.finish_min <= a.start_min)) SELECT first_job, second_job, saved_packages, cost_cents FROM plans WHERE cost_cents <= 90 ORDER BY saved_packages DESC, cost_cents, first_job, second_job LIMIT 1",
  "decision-score-slip-print-order": "WITH qty(q) AS (VALUES (0), (1), (2), (3), (4), (5), (6)), orders AS (SELECT nq.q AS narrow_packs, wq.q AS wide_packs, nq.q * n.slips + wq.q * w.slips AS total_slips, nq.q * n.pack_cents + wq.q * w.pack_cents + CASE WHEN nq.q > 0 THEN n.setup_cents ELSE 0 END + CASE WHEN wq.q > 0 THEN w.setup_cents ELSE 0 END AS cost_cents FROM pack_offer AS n CROSS JOIN pack_offer AS w JOIN qty AS nq ON nq.q <= n.stock JOIN qty AS wq ON wq.q <= w.stock WHERE n.format_id = 'narrow' AND w.format_id = 'wide') SELECT narrow_packs, wide_packs, total_slips, cost_cents FROM orders CROSS JOIN print_job WHERE total_slips BETWEEN need_slips AND capacity_slips ORDER BY cost_cents, total_slips, narrow_packs LIMIT 1",
  "decision-select-capped-bonus-offers-within-monthly-pool": "WITH RECURSIVE masks(bits) AS (VALUES (0) UNION ALL SELECT bits + 1 FROM masks WHERE bits < 127), plans AS (SELECT m.bits AS selected_bits, coalesce(sum(o.retained_count), 0) AS retained_total, coalesce(sum(min(o.earned_cents, o.ceiling_cents)), 0) AS payout_cents FROM masks AS m LEFT JOIN campaign_offers AS o ON (m.bits & o.offer_bit) <> 0 GROUP BY m.bits HAVING coalesce(sum(o.offer_bit), 0) = m.bits AND count(o.offer_bit) = count(DISTINCT o.catalog_id)) SELECT selected_bits, retained_total, payout_cents FROM plans CROSS JOIN bonus_pool WHERE payout_cents <= budget_cents ORDER BY retained_total DESC, payout_cents, selected_bits LIMIT 1"
}
